import { z } from 'zod';
import type { DynamicToolSpec } from './dynamic-tools';

export const USER_INTERACTION_TOOL_NAME = 'user_interaction';
export const USER_INTERACTION_REQUEST_METHOD = 'interaction/request';

const text = z.string().trim().min(1).max(2000);
export const InteractionQuestion = z.object({
  id: z.string().trim().min(1).max(80),
  question: text,
  options: z.array(z.object({ label: text, description: text.optional() }).strict()).max(6).default([]),
  defaultAnswer: text.optional(),
}).strict();

export const UserInteractionArgs = z.object({
  kind: z.enum(['input', 'preference', 'confirmation']),
  title: text,
  message: text.optional(),
  skillCredit: z.object({
    skill: z.enum(['hi3d-model-gpt-animation', 'image-to-assembly', 'mask-design']),
    credits: z.number().int().positive(),
  }).strict().optional(),
  questions: z.array(InteractionQuestion).max(3).default([]),
  timeoutSeconds: z.number().int().min(60).max(600).optional(),
}).strict().superRefine((value, ctx) => {
  const issue = (message: string) => ctx.addIssue({ code: 'custom', message });
  if (value.kind === 'confirmation') {
    if (!value.message || value.questions.length) issue('A confirmation must describe the specific action and must not include questions');
  } else if (!value.questions.length) issue('At least one question is required');
  if (new Set(value.questions.map((q) => q.id)).size !== value.questions.length) issue('Question IDs must be unique');
  for (const q of value.questions) {
    if (new Set(q.options.map((o) => o.label)).size !== q.options.length) issue('Option labels must be unique');
    if (value.kind === 'preference' && (!q.defaultAnswer || !q.options.some((o) => o.label === q.defaultAnswer))) {
      issue('Preference questions require options and a matching defaultAnswer');
    }
    if (value.kind !== 'preference' && q.defaultAnswer !== undefined) issue('Only preference questions may have a default answer');
  }
  if (value.kind !== 'preference' && value.timeoutSeconds !== undefined) issue('Input and confirmation requests must not have timeout defaults');
});
export type UserInteractionArgs = z.infer<typeof UserInteractionArgs>;

export const UserInteractionResponse = z.object({
  status: z.enum(['answered', 'defaulted', 'declined', 'cancelled']),
  source: z.enum(['user', 'assistant_default']),
  answers: z.record(z.string(), z.string()),
  decision: z.enum(['accept', 'decline']).optional(),
}).strict();
export type UserInteractionResponse = z.infer<typeof UserInteractionResponse>;

export function parseInteractionResponse(args: UserInteractionArgs, raw: unknown): UserInteractionResponse | null {
  const parsed = UserInteractionResponse.safeParse(raw);
  if (!parsed.success) return null;
  const result = parsed.data;
  if (result.status === 'cancelled') return result.source === 'user' && !result.decision && !Object.keys(result.answers).length ? result : null;
  if (args.kind === 'confirmation') {
    return result.source === 'user' && !Object.keys(result.answers).length
      && ((result.status === 'answered' && result.decision === 'accept') || (result.status === 'declined' && result.decision === 'decline')) ? result : null;
  }
  if (result.decision || Object.keys(result.answers).length !== args.questions.length) return null;
  if (result.status === 'answered' && result.source === 'user' && args.questions.every((q) => !!result.answers[q.id]?.trim())) return result;
  return args.kind === 'preference' && result.status === 'defaulted' && result.source === 'assistant_default'
    && args.questions.every((q) => result.answers[q.id] === q.defaultAnswer) ? result : null;
}


export const USER_INTERACTION_DYNAMIC_TOOLS: DynamicToolSpec[] = [{
  name: USER_INTERACTION_TOOL_NAME,
  description: 'Collect user input, preferences, or authorization through a host interaction panel for any task, not just Hi3D or skills. A panel appears only when this tool is called; ordinary chat cannot create one. If arguments are rejected, correct them and retry. Never claim to be waiting for a panel that was not created.',
  inputSchema: z.toJSONSchema(UserInteractionArgs),
}];
